/**
 * multipart/form-data: `file` (до 2 ГБ) идёт потоком в S3, без
 * промежуточного диска. Для видео браузер присылает кадр `thumbnail` и
 * размеры. Картинкам превью делает сервер.
 * @summary Загрузить файл
 */
export const uploadMediaAsset = (
  uploadAssetBody: BodyType<UploadAssetBody>,
  options?: SecondParameter<typeof customInstance>,
  signal?: AbortSignal,
) => {
  const formData = new FormData();
  formData.append(`file`, uploadAssetBody.file);
  if (uploadAssetBody.thumbnail !== undefined) {
    formData.append(`thumbnail`, uploadAssetBody.thumbnail);
  }
  if (uploadAssetBody.title !== undefined) {
    formData.append(`title`, uploadAssetBody.title);
  }
  if (uploadAssetBody.tags !== undefined) {
    formData.append(`tags`, uploadAssetBody.tags);
  }
  if (uploadAssetBody.width !== undefined) {
    formData.append(`width`, uploadAssetBody.width.toString());
  }
  if (uploadAssetBody.height !== undefined) {
    formData.append(`height`, uploadAssetBody.height.toString());
  }
  if (uploadAssetBody.durationSec !== undefined) {
    formData.append(`durationSec`, uploadAssetBody.durationSec.toString());
  }

  return customInstance<MediaAssetResponse>(
    {
      url: `/media/assets`,
      method: "POST",
      headers: { "Content-Type": "multipart/form-data" },
      data: formData,
      signal,
    },
    options,
  );
};

